from flask import Flask, request, jsonify, g
import requests
import hashlib
import hmac
import ipaddress
import socket
from urllib.parse import urlparse
from functools import wraps

app = Flask(__name__)

# Multi-tenant configuration store (simulated)
TENANT_CONFIGS = {
    "tenant_alpha": {"webhook_domain": "hooks.alpha-corp.com", "secret": "alpha_secret_key_2024"},
    "tenant_beta": {"webhook_domain": "hooks.beta-inc.io", "secret": "beta_secret_key_2024"},
}

BLOCKED_RANGES = [
    ipaddress.ip_network("10.0.0.0/8"),
    ipaddress.ip_network("172.16.0.0/12"),
    ipaddress.ip_network("192.168.0.0/16"),
    ipaddress.ip_network("127.0.0.0/8"),
    ipaddress.ip_network("169.254.0.0/16"),
]

def verify_tenant(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        tenant_id = request.headers.get("X-Tenant-ID")
        signature = request.headers.get("X-Request-Signature")
        if not tenant_id or tenant_id not in TENANT_CONFIGS:
            return jsonify({"error": "Invalid tenant"}), 403
        if not signature:
            return jsonify({"error": "Missing signature"}), 403
        expected_sig = hmac.new(
            TENANT_CONFIGS[tenant_id]["secret"].encode(),
            tenant_id.encode(),
            hashlib.sha256
        ).hexdigest()
        # Verify the provided signature in constant time.
        if not hmac.compare_digest(expected_sig, signature):
            return jsonify({"error": "Invalid signature"}), 403
        g.tenant_id = tenant_id
        g.tenant_config = TENANT_CONFIGS[tenant_id]
        return f(*args, **kwargs)
    return decorated

def is_ip_blocked(ip_str):
    """Check if an IP address falls within blocked internal ranges."""
    try:
        addr = ipaddress.ip_address(ip_str)
        for network in BLOCKED_RANGES:
            if addr in network:
                return True
        return False
    except ValueError:
        return True

def validate_webhook_target(url, tenant_config):
    """Validate that webhook URL belongs to tenant's registered domain.
    Performs DNS resolution and checks against blocked IP ranges."""
    parsed = urlparse(url)

    if parsed.scheme not in ("http", "https"):
        return False, "Invalid scheme"

    hostname = parsed.hostname
    if not hostname:
        return False, "No hostname"

    # Verify the hostname matches tenant's registered webhook domain
    allowed_domain = tenant_config["webhook_domain"]
    if not (hostname == allowed_domain or hostname.endswith("." + allowed_domain)):
        return False, f"Domain not allowed for tenant. Must be {allowed_domain} or subdomain"

    # Resolve DNS and check for SSRF via DNS rebinding protection
    try:
        resolved_ip = socket.gethostbyname(hostname)
    except socket.gaierror:
        return False, "DNS resolution failed"

    if is_ip_blocked(resolved_ip):
        return False, "Target resolves to blocked IP range"

    return True, resolved_ip

def dispatch_webhook(url, payload, resolved_ip):
    """Send webhook request to validated URL.
    Uses resolved IP to prevent DNS rebinding between validation and request."""
    parsed = urlparse(url)
    # Reconstruct URL with resolved IP to prevent TOCTOU DNS rebinding
    safe_url = f"{parsed.scheme}://{resolved_ip}{parsed.path}"
    if parsed.query:
        safe_url += f"?{parsed.query}"

    headers = {
        "Host": parsed.hostname,
        "Content-Type": "application/json",
        "X-Webhook-Source": "solidity-bridge"
    }

    try:
        resp = requests.post(safe_url, json=payload, headers=headers, timeout=5, allow_redirects=False)
        return resp.status_code, resp.text[:500]
    except requests.RequestException as e:
        return 0, str(e)

@app.route("/api/v1/contract-event", methods=["POST"])
@verify_tenant
def handle_contract_event():
    """Receives Solidity contract events and forwards to tenant webhook."""
    data = request.get_json()
    if not data:
        return jsonify({"error": "Invalid JSON"}), 400

    callback_url = data.get("callback_url")
    event_data = data.get("event", {})

    if not callback_url:
        return jsonify({"error": "callback_url required"}), 400

    # Validate the webhook target
    valid, result = validate_webhook_target(callback_url, g.tenant_config)
    if not valid:
        return jsonify({"error": f"Invalid webhook target: {result}"}), 403

    # result contains the resolved IP when valid
    status, body = dispatch_webhook(callback_url, event_data, result)

    return jsonify({"status": status, "response_preview": body[:200]})

@app.route("/api/v1/batch-notify", methods=["POST"])
@verify_tenant
def handle_batch_notify():
    """Batch notification endpoint for multiple contract events."""
    data = request.get_json()
    if not data or "notifications" not in data:
        return jsonify({"error": "Invalid payload"}), 400

    results = []
    for notification in data["notifications"][:10]:  # Max 10 per batch
        url = notification.get("url")
        payload = notification.get("payload", {})

        if not url:
            results.append({"error": "missing url"})
            continue

        valid, result = validate_webhook_target(url, g.tenant_config)
        if not valid:
            results.append({"error": result})
            continue

        status, body = dispatch_webhook(url, payload, result)
        results.append({"status": status})

    return jsonify({"results": results})

@app.route("/internal/health", methods=["GET"])
def health_check():
    return jsonify({"status": "healthy", "service": "solidity-webhook-bridge"})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8080)
